"""Literal raw city DataFrames + synthetic-dir builder for Step 05 tests.

Pure literal ``pd.DataFrame``s + ``build_synthetic_raw_dir()`` helper.
No ``@pytest.fixture`` decorators — same style as
``tests/fixtures/facet_decode_fixtures.py`` and
``tests/fixtures/parse_fixtures.py``.

Each fixture here corresponds to a small slice of one of the real city
CSVs in ``data/raw/``. The shapes (column names, dtypes, value formats)
match what the actual CSVs contain so the per-city mappers exercise the
same code paths the real-data DoD test hits.
"""

from __future__ import annotations

from pathlib import Path
from typing import Final

