# ===========================================================================
# Synthetic-dir builder
# ===========================================================================


# Mapping: city-name → (filename, raw DataFrame) for the helper.
_RAW_FILES: Final[dict[str, tuple[str, pd.DataFrame]]] = {
    "Gurgaon": ("gurgaon_10k.csv", GURGAON_RAW_DF),
    "Hyderabad": ("hyderabad.csv", HYDERABAD_RAW_DF),
    "Kolkata": ("kolkata.csv", KOLKATA_RAW_DF),
    "Mumbai": ("mumbai.csv", MUMBAI_RAW_DF),
}


def build_synthetic_raw_dir(tmp_path: Path) -> Path:
    """Write 4 city CSVs + ``facets/`` under ``tmp_path/raw/`` and return
    the synthetic data dir (parent of ``raw/`` — what
    ``ingest.load_raw_listings`` expects).

    Mirrors the layout of ``data/raw/`` so the same ingestion code paths
    work. Used by tests that need a real on-disk CSV (immutability tests,
    snapshot tests, end-to-end dispatch tests).
    """
    raw_dir = tmp_path / "raw"
    raw_dir.mkdir(parents=True, exist_ok=True)
    for filename, df in _RAW_FILES.values():
        df.to_csv(raw_dir / filename, index=False)
    build_synthetic_facets_dir(tmp_path)
    return tmp_path


def facet_frames_for_tests() -> dict[str, pd.DataFrame]:
    """Return a dict of facet DataFrames with their ``_index`` attached,
    so the per-city mappers can use them directly. Mirrors what
    ``load_facet_frames`` returns for the synthetic facets dir.

    The 15 facet DFs are the same constants used by the Step 04 tests
    (imported above); we re-attach the index here so callers don't have
    to import the helper from ``test_facet_decoders``.
    """
    # Build fresh dicts (Step 04 attaches the index at import time; we
    # defensively re-attach in case the import-time side-effect didn't
    # run for any reason).
    frames: dict[str, pd.DataFrame] = {
        "AGE": AGE_DF.copy(),
        "AMENITIES": AMENITIES_DF.copy(),
        "BATHROOM_NUM": BATHROOM_NUM_DF.copy(),
        "BEDROOM_NUM": BEDROOM_NUM_DF.copy(),
        "BUILDING_ID": BUILDING_ID_DF.copy(),
        "CITY": CITY_DF.copy(),
        "FACING_DIRECTION": FACING_DF.copy(),
        "FEATURES": FEATURES_DF.copy(),
        "FLOOR_NUM": FLOOR_NUM_DF.copy(),
        "FURNISH": FURNISH_DF.copy(),
        "LOCALITY_ID": LOCALITY_ID_DF.copy(),
        "OWNERSHIP_TYPE": OWNTYPE_DF.copy(),
        "PROPERTY_TYPE": PROPERTY_TYPE_DF.copy(),
        "SUB_AVAILABILITY": SUB_AVAILABILITY_DF.copy(),
        "TOTAL_FLOOR": TOTAL_FLOOR_DF.copy(),
    }
    for facet_df in frames.values():
        index: dict[str, str] = {}
        for _, row in facet_df.iterrows():
            if pd.isna(row["id"]):
                continue
            index[str(row["id"])] = str(row["label"])
        facet_df.attrs["_index"] = index
        facet_df.attrs["decode_stats"] = {}
    return frames
